import csv,json,pathlib,sys
base,out=map(pathlib.Path,sys.argv[1:]);out.mkdir(parents=True,exist_ok=True)
f=base/'bilan-par-outil.csv';r=csv.DictReader(f.open(encoding='utf-8-sig'),delimiter=';');fields=list(r.fieldnames);rows=list(r)
extra=['fonctionnement_demontre_2nov','actualisation_partielle_2nov','usages_bloques_2nov','preuves_2nov','limites_2nov'];fields += [x for x in extra if x not in fields]
scoped={
 '/calculateur-investissement':('12cotations exactes supplémentaires publiées par reprise automatique41379698791, jusqu’à octobre2026 ;24calculs publics EUR/ordinateur et USD/mobile,26PNG avec la comparaison. Bitcoin142mois ;14actions non-bond et SBUX déjà vérifiés conservés.','Neuf anciens cas annuels sans voie mensuelle admise, cinq bornesNAV/TR octobre refusées, orBanque mondiale encore septembre et FTSE incomplet ; dates/périodes explicites, pas d’extrapolation ni substitution.'),
 '/classements-performances':('12voies de comparaison mensuelle supplémentaires ; deux devises et13PNG par famille de tests avec le calculateur. Sélection des21fonds au classement annuel vérifiée sur ordinateur/mobile ; calendriers annuels ne sont pas comptés comme nouvelles voies mensuelles.','70/79anciennes fenêtres mensuelles admises,9refusées ; périodes communes, années complètes, devises, couleurs et ex aequo préservés.'),
 '/generateur-portefeuilles':('Rôle émergents conservé pour la vraie cotation Brazil ;21fonds recherchés/sélectionnés en mode manuel, calculs et exports publics sur ordinateur/mobile. Cours ajustésEUR distincts des NAVUSD.','Aucune admission automatique massive ; les rôles et contraintes des recettes restent qualifiés séparément, PEAinconnu non admis comme vrai.'),
 '/duels-portefeuilles':('21fonds sélectionnés dans les Duels manuels, calculs indépendants des13bornes mensuelles par année et du change ; exports publics ordinateur/mobile.','Ne pas assimiler un calendrierNAVUSD à une cotation ajustéeEUR ; profondeur réellement commune appliquée.'),
 '/le-dca-de':('11premières compositions physiques exactes du lot#1130 réellement collectées et consommées,22PNG identiques aux aperçus. Neuf admissibles au recouvrement intégral ; Brésil et Japon petites capitalisations restent partiels. Recouvrement qualifié et partiel, consolidation exacte et invariance à l’ordre vérifiés,4PNG. QuatreWisdomTree : lignes pays/secteurs exactes et8PNG publics supplémentaires ; une composition complète plus récente reste prioritaire.','Pas de renormalisation :99,07286% et98,74657% d’actions pour les deux cas partiels. Deux rafraîchissements completsWisdomTree régressifs, ligne monétaireGlobalX sans poids (livres du28octobre conservés, pas d’indisponibilité générale), conflitsQYLD et compositions d’indices non qualifiées restent distincts.'),
 '/fiches-etf':('Sept encoursWisdomTree réels en devise native, fiches etPNG publics vérifiés ; caractéristiques et calendriers du catalogue conservés. Le secours exact des rankings est vérifié dans GitHub :12champs datés23octobre, aucun encours ou indice reconstruit.','Deux encoursPEA : primaireGHA403, PDFmensuel accessible mais plus ancien que la valeur conservée.23statutsPEA non qualifiés après ajout concurrent des21fonds, dont les2cas historiques ; inconnu/conflit conservés.'),
 '/performance-depuis':('Convention du support sélectionné vérifiée pour21parts, en devise native,42PNG dans le test isolé et recette complèteGitHub ; les12cotations ne portent pas une mentionVL erronée. Aucun texte applicatif réécrit.','Les calendriers annuels restent utilisables indépendamment des neuf fenêtres mensuelles refusées ; couverture et périodes réellement disponibles appliquées.'),
 '/presentations':('Enregistrement acteurs32cad6e après#1137,11contrôles source réussis,42fichiers publics vérifiés ; blocage d’enregistrement distinct des données financières, qui sont inchangées.','SCPI : publication non annoncée ne vaut pas panne ; dates de photographie/contrôle/bulletin distinctes. Conditions propres aux projets non inférées depuis les fiches générales.'),
 '/radar-editorial':('Rapport natif compact complet passé de8052546à6068876octets sans suppression de champ ni hausse du plafond8000000 ;62statuts individuels et leur plan validés. Les rapports récents sont ingérés par le moniteur public.','Les échecs fournisseur et conflits de photographie restent du chantierRadar ; un nouveau rapport lisible ne résout pas ces sources ni les vieux rapports historiquement illisibles.'),
 '/donnees-a-revoir':('Contrat des210attentes mal attribuées par passage corrigé (420diagnostics sur2anciens rapports publics) : champs possédés déclarés avant collecte, identités anciennes conservées ; ne certifie pas les105autres couples instrument/champ. Dates et étapes de collecte/enregistrement/publication restent séparées.','Les qualifications par usage ne sont pas des pannes ; ancien périmètre inconnu et rapports incomplets restent historiques. Voir preuves réelles du passage ciblé, distinct du test du plan.'),
 '/bibliotheque-donnees':('ExportJSON et recherches conservés.42ambiguïtés de liaison résolues parISIN+MIC+devise+ticker+symbole exacts, reconstruits en lecture seule dans les deux arbresGit ; aucun actif ni cotation supprimé.','Ce rapprochement documentaire ne certifie pas les valeurs, périodes ou conventions ; les anciens identifiants sont conservés.'),
}
for x in rows:
 route=x['route'];removed='périmètre supprimé'in x.get('perimetre_1nov','')
 if removed:
  x.update(fonctionnement_demontre_2nov='Périmètre supprimé ; trace conservée, aucun automatisme restauré.',actualisation_partielle_2nov='non applicable',usages_bloques_2nov='non applicable',preuves_2nov=x.get('preuve_1nov',''),limites_2nov='Ne compte ni comme donnée réparée ni comme panne.')
 else:
  result,limit=scoped.get(route,(x.get('fonctionnement_demontre_1nov')or x.get('corrections_et_usages',''),'Pas de nouvelle certification de cette famille dans ce complément ; preuves antérieures, données et limites conservées.'))
  x.update(fonctionnement_demontre_2nov=result,actualisation_partielle_2nov=x.get('actualisation_partielle_1nov')or x.get('limites_et_usages_bloques',''),usages_bloques_2nov=limit,preuves_2nov='preuves/reprise-2026-11-02/RESULTATS.md ; matrice unique et preuves bornées par source/consommateur',limites_2nov='Les nouvelles données du catalogue#1130 et leurs premières preuves sont créditées séparément des réparations et des79anciens cas. Passage manuel/reprise automatique/cron distingués ; pas d’automatisation totale annoncée.')
with (out/'bilan-par-outil.csv').open('w',newline='',encoding='utf-8-sig')as f:w=csv.DictWriter(f,fieldnames=fields,delimiter=';',lineterminator='\n');w.writeheader();w.writerows(rows)
print('All',len(rows),'tool rows preserved;',sum('périmètre supprimé'in r.get('perimetre_1nov','')for r in rows),'historical removed scopes kept')
